      ]
    },
    "sales_overview_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "overview_heading_stack",
        "intro_text",
        "product_sales_table",
        "top_performer_text"
      ]
    },
    "overview_heading_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "graph_icon",
        "overview_heading"
      ]
    },
    "graph_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000661_01_1_graph-up.svg"
      },
      "children": []
    },
    "overview_heading": {
      "type": "Text",
      "props": {
        "text": "Quarterly Sales Overview & Top Performer",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "The following data presents the quarterly sales performance for each product."
      },
      "children": []
    },
    "product_sales_table": {
      "type": "Table",
      "props": {
        "statePath": "/productSalesTable",
        "columns": [
          {
            "key": "product",
            "label": "Product"
          },
          {
            "key": "q1",
            "label": "Q1"
          },
          {
            "key": "q2",
            "label": "Q2"
          },
          {
            "key": "q3",
            "label": "Q3"
          },
          {
            "key": "q4",
            "label": "Q4"
          },
          {
            "key": "totalAnnualSales",
            "label": "Total Annual Sales"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "product",
        "highlightColumns": [
          "totalAnnualSales"
        ],
        "numericColumns": [
          "q1",
          "q2",
          "q3",
          "q4",
          "totalAnnualSales"
        ]
      },
      "children": []
    },
    "top_performer_text": {
      "type": "Text",
      "props": {
        "text": "Top Performer: Product C achieved the highest total sales for the year with 620 units."
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "quick_actions_heading",
        "generate_report_button",
        "analyze_trends_button"
      ]
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "generate_report_button": {
      "type": "Button",
      "props": {
        "label": "Generate Full Sales Report"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/generate_sales_report"
          }
        }
      },
      "children": []
    },
    "analyze_trends_button": {
      "type": "Button",
      "props": {
        "label": "Analyze Product Trends"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://example.com/analyze_product_trends"
          }
        }
      },
      "children": []
    }
  }
